sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float hue;
uniform float saturation;
uniform float vibrance;
uniform float lightness;
half luma(half3 c) { return dot(c, half3(0.2126, 0.7152, 0.0722)); }
half4 main(float2 coord) {
    half4 c = unpremul(image.eval(coord));
    float3 k = float3(0.57735);
    float a = radians(hue);
    float3 v = float3(c.rgb);
    v = v * cos(a) + cross(k, v) * sin(a) + k * dot(k, v) * (1 - cos(a));
    half3 rgb = half3(v);
    rgb = mix(half3(luma(rgb)), rgb, half(saturation));
    half chromaNow = max(rgb.r, max(rgb.g, rgb.b)) - min(rgb.r, min(rgb.g, rgb.b));
    rgb = mix(half3(luma(rgb)), rgb, half(1.0 + vibrance * (1.0 - saturate(chromaNow)))) + half(lightness);
    return half4(saturate(rgb) * c.a, c.a);
}
